#nullable enable
using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text.Json;
using System.Threading.Tasks;

namespace EastFive.Configuration
{
    /// <summary>How generated bytes are written as text.</summary>
    public enum ConfigurationRandomEncoding
    {
        /// <summary>RFC 4648 §5, unpadded: safe in a URL query and a header.</summary>
        Base64Url,
        Base64,
        /// <summary>Lowercase hexadecimal.</summary>
        Hex,
    }

    /// <summary>A named curve an EC key is on (<c>EastFive.Security.EcKeyAttribute</c>).</summary>
    public enum ConfigurationEcCurve
    {
        P256,
        P384,
        P521,
    }

    /// <summary>
    /// The base of the built-in generators: fills the member it is declared on, optionally a key-id
    /// member of the same type (<see cref="KeyIdMember"/>, a dated id), and adds the declared
    /// <see cref="Instruction"/>.
    /// </summary>
    [AttributeUsage(AttributeTargets.Property, AllowMultiple = false, Inherited = true)]
    public abstract class ConfigurationValueGeneratorAttribute : Attribute, IGenerateConfigurationValue
    {
        public abstract string Label { get; }

        /// <summary>What this generator asks the user for; none by default.</summary>
        public virtual IReadOnlyList<ConfigurationGenerationInput> Inputs => Array.Empty<ConfigurationGenerationInput>();

        /// <summary>A member of the same type that receives the new value's id: a key pair's RFC 7638
        /// thumbprint, otherwise a dated id (<c>yyyy-MM-dd-xxxxxxxx</c>).</summary>
        public string? KeyIdMember { get; init; }

        /// <summary>A step to take outside configuration once the value is generated.</summary>
        public string? Instruction { get; init; }

        /// <summary>Where <see cref="Instruction"/> is done.</summary>
        public string? InstructionLink { get; init; }

        /// <summary>The member's value and any outputs; <paramref name="keyId"/> is the id the
        /// key-id member receives, for a generator that publishes it (a JWK's kid). Drawn only when read.</summary>
        protected abstract ConfigurationGenerationResult Generate(ConfigurationGenerationContext context, Lazy<string> keyId);

        public Task<ConfigurationGenerationResult> GenerateAsync(ConfigurationGenerationContext context)
        {
            var keyId = new Lazy<string>(context.NewKeyId);
            var result = Generate(context, keyId);
            if (KeyIdMember != null && !result.Values.ContainsKey(KeyIdMember))
                result = result.WithValue(KeyIdMember, keyId.Value);
            if (Instruction != null)
                result = result.WithInstruction(Instruction, InstructionLink);
            return Task.FromResult(result);
        }

        internal static string Encode(byte[] bytes, ConfigurationRandomEncoding encoding)
            => encoding switch
            {
                ConfigurationRandomEncoding.Base64 => Convert.ToBase64String(bytes),
                ConfigurationRandomEncoding.Hex => Convert.ToHexString(bytes).ToLowerInvariant(),
                _ => Base64Url(bytes),
            };

        internal static string Base64Url(byte[] bytes)
            => Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');

        internal static string EncodingName(ConfigurationRandomEncoding encoding)
            => encoding switch
            {
                ConfigurationRandomEncoding.Base64 => "base64",
                ConfigurationRandomEncoding.Hex => "hex",
                _ => "base64url",
            };

        /// <summary>A JWKS document holding one public key (members in the order RFC 7517 examples use).</summary>
        internal static string Jwks(IEnumerable<KeyValuePair<string, string>> jwk)
        {
            var key = new Dictionary<string, string>();
            foreach (var (name, value) in jwk)
                key[name] = value;
            return JsonSerializer.Serialize(new Dictionary<string, object> { ["keys"] = new[] { key } },
                new JsonSerializerOptions { WriteIndented = true });
        }

        /// <summary>The key-pair outputs: the public key (PEM), the JWKS and, when no member receives
        /// it, the key id to copy.</summary>
        protected ConfigurationGenerationResult WithKeyPairOutputs(ConfigurationGenerationResult result,
            string publicKeyPem, IEnumerable<KeyValuePair<string, string>> jwk, string keyId)
        {
            result = result
                .WithOutput("Public key (PEM)", publicKeyPem, ConfigurationOutputKind.Pem)
                .WithOutput("JWKS", Jwks(jwk), ConfigurationOutputKind.Json);
            return KeyIdMember == null ? result.WithOutput("Key id", keyId) : result;
        }
    }

    /// <summary>Random bytes of <see cref="Length"/>, written in <see cref="Encoding"/> (default base64url).</summary>
    public sealed class GenerateRandomBytesAttribute : ConfigurationValueGeneratorAttribute
    {
        public GenerateRandomBytesAttribute(int length = 32)
        {
            if (length is < 1 or > 1024)
                throw new ArgumentOutOfRangeException(nameof(length), length, "Generate 1 to 1024 random bytes.");
            Length = length;
        }

        public int Length { get; }

        public ConfigurationRandomEncoding Encoding { get; init; } = ConfigurationRandomEncoding.Base64Url;

        public override string Label => $"Random {Length} bytes, {EncodingName(Encoding)}";

        protected override ConfigurationGenerationResult Generate(ConfigurationGenerationContext context, Lazy<string> keyId)
            => ConfigurationGenerationResult.Of(context.Member.Property.Name, Encode(context.RandomBytes(Length), Encoding));
    }

    /// <summary>A random (version 4) GUID in <see cref="Format"/> (a <see cref="Guid.ToString(string)"/> format; default "D").</summary>
    public sealed class GenerateGuidAttribute : ConfigurationValueGeneratorAttribute
    {
        private readonly string format = "D";

        public string Format
        {
            get => format;
            init => format = value is "D" or "N" or "B" or "P"
                ? value
                : throw new ArgumentException($"'{value}' is not a GUID format this generator writes (D, N, B or P).", nameof(Format));
        }

        public override string Label => Format == "D" ? "GUID" : $"GUID ({Format})";

        protected override ConfigurationGenerationResult Generate(ConfigurationGenerationContext context, Lazy<string> keyId)
        {
            var bytes = context.RandomBytes(16);
            bytes[7] = (byte)((bytes[7] & 0x0F) | 0x40); // version 4 (Guid's little-endian layout)
            bytes[8] = (byte)((bytes[8] & 0x3F) | 0x80); // RFC 4122 variant
            return ConfigurationGenerationResult.Of(context.Member.Property.Name, new Guid(bytes).ToString(Format));
        }
    }
}
